import{_ as e,o as r,a,b as o}from"./app.C41L12d5.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"guide/operator_practice/typical_operator_cases/simd_operator_impl/gelu_reg_vector_operator/extreme_optimization.md","filePath":"guide/operator_practice/typical_operator_cases/simd_operator_impl/gelu_reg_vector_operator/extreme_optimization.md","outlineHeaders":[{"level":2,"title":"残余瓶颈分析","slug":"残余瓶颈分析","link":"#残余瓶颈分析"},{"level":2,"title":"极致打磨手段：循环展开优化","slug":"极致打磨手段：循环展开优化","link":"#极致打磨手段：循环展开优化"},{"level":2,"title":"终极性能达成","slug":"终极性能达成","link":"#终极性能达成"}],"lastUpdated":1786954352000}'),l={name:"guide/operator_practice/typical_operator_cases/simd_operator_impl/gelu_reg_vector_operator/extreme_optimization.md"};function i(n,t,s,d,c,p){return r(),a("div",null,[...t[0]||(t[0]=[o(`<div><article class="markdown-body"><h1>高阶极限打磨<span id="ZH-CN_TOPIC_000000_GELU_ADV"></span></h1><p>本节在中级性能优化的基础上，介绍GELU算子的高阶极限打磨方法。</p><h2 id="残余瓶颈分析">残余瓶颈分析<a class="header-anchor" href="#残余瓶颈分析">​</a></h2><p>中级优化后IPC为1.20，距离VF融合理论极限IPC=2.0仍有较大差距。残余瓶颈主要体现在：</p><ul><li><strong>瓶颈1：VF函数循环内指令依赖链过长</strong>：GELU计算包含8条向量指令，形成较长的依赖链，编译器在有限执行队列中调度的循环次数太少，导致每cycle可双发的指令数不足，IPC仅为1.20。</li><li><strong>瓶颈2：循环控制标量开销</strong>：for循环的变量更新、条件判断引入标量指令，在向量指令大幅缩短后相对占比上升。</li></ul><h2 id="极致打磨手段：循环展开优化">极致打磨手段：循环展开优化<a class="header-anchor" href="#极致打磨手段：循环展开优化">​</a></h2><p><strong>原理</strong>：通过<code>#pragma unroll N</code>告诉编译器将循环展开N份，消除循环控制开销，同时使多组迭代的VF指令可交错排布，提高指令级并行度（ILP），使更多指令能够连续双发射。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>未展开：                         展开后：
Iter0: Load→Mul→...→Store       Iter0: Load→Mul→...→Store
  ↓ (循环控制开销)               Iter1: Load→Mul→...→Store
Iter1: Load→Mul→...→Store       Iter2: Load→Mul→...→Store
  ↓ (循环控制开销)               Iter3: Load→Mul→...→Store
Iter2: Load→Mul→...→Store       ...（无循环控制开销，指令可交错排布）
</code></pre></div><p><strong>优化方案</strong>：在VF函数的for循环前添加<code>#pragma unroll 6</code>，展开因子6为经验值，需根据实际场景调优。</p><p><strong>展开因子选择建议</strong>：</p><ul><li>展开过多：增加寄存器压力，可能导致溢出，性能反而劣化</li><li>展开过少：优化效果不明显</li><li>建议：逐次尝试2、4、6、8等值，找到最优展开次数</li></ul><h2 id="终极性能达成">终极性能达成<a class="header-anchor" href="#终极性能达成">​</a></h2><table><thead><tr><th align="left">指标</th><th align="center">入门版（基准）</th><th align="center">中级优化版（VF融合）</th><th align="center">高阶打磨版（VF融合+循环展开）</th></tr></thead><tbody><tr><td align="left">Task Duration(μs)</td><td align="center">351.525</td><td align="center">348.868</td><td align="center"><strong>344.436</strong></td></tr><tr><td align="left">aiv_vec_time(μs)</td><td align="center">147.895</td><td align="center">66.277</td><td align="center"><strong>63.655</strong></td></tr><tr><td align="left">IPC</td><td align="center">-</td><td align="center">1.20</td><td align="center"><strong>1.25</strong></td></tr></tbody></table><p><strong>关键验证指标</strong>：</p><ul><li>向量指令耗时从入门版的147.895μs降至<strong>63.655μs</strong>，减少<strong>56.9%</strong></li><li>IPC从中级优化版的1.20提升至<strong>1.25</strong>，提升<strong>4.2%</strong></li><li>当前IPC为1.25，距离理论极限2.0仍有空间，主要受限于GELU 8条指令的依赖链长度</li></ul><p><strong>进一步提升IPC的方向</strong>：将过长的loop循环切分为多个短循环，在长latency指令（如Exp、Div）结束点进行拆分，使每组依赖链更短，双发效率更高。本样例loop循环较短，不适用于该优化项。</p><p>详细内容请参见<a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/05_best_practices/02_reg_compute/gelu_high_performance/README.md#case-2-%E5%90%AF%E7%94%A8regbase-apivf%E8%9E%8D%E5%90%88%E8%83%BD%E5%8A%9B%E5%92%8C%E5%BE%AA%E7%8E%AF%E5%B1%95%E5%BC%80%E4%BC%98%E5%8C%96">Gelu性能调优样例 Case 2</a>。</p></article></div>`,1)])])}const h=e(l,[["render",i]]);export{_ as __pageData,h as default};
